import { useCallback, useEffect, useState } from 'react';
import type {
  CardData,
  CommanderId,
  Commanders,
  Direction,
  GameState,
  LogEntry,
  Mechanic,
  TrackedCard,
  TurnChange,
} from '../types';
import { COMMANDER_NAME } from '../utils/commanders';
